export const GEOMETRY_EPSILON=precision.panelGeometry;
export const PANEL_SNAP_PIXELS=precision.panelSnapPixels;
export const panelSnapTolerance=(zoom=1)=>PANEL_SNAP_PIXELS/Math.max(.01,zoom);
const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),lerp=(a,b,t)=>({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t});
